def rbs_upstream(s, pos, maxgap=13):
    # sequence s, coding start at pos (0-based) in s; look upstream (s[pos-gap:pos])
    for gap in range(4, maxgap+1):
        up = s[max(0,pos-gap):pos]
        if up.endswith('GGAGG') or up.endswith('AGGAG') or up.endswith('GGAG') or up.endswith('AGGA'):
            return (gap, up)
    return None

