import random, copy, statistics
seq = ''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
comp = str.maketrans('ACGT','TGCA')
stop={'TAA','TAG','TGA'}
def orf_sizes(s):
    out=[]
    for f in range(3):
        sub=s[f:]; run=0
        for i in range(0,len(sub)-2,3):
            if sub[i:i+3] in stop:
                if run>=300: out.append(run)
                run=0
            else: run+=3
        if run>=300: out.append(run)
    return out
def allorf(s):
    r=s.translate(comp)[::-1]
    return orf_sizes(s)+orf_sizes(r)

def dinuc_shuffle(s):
    d=copy.deepcopy({})
    counts={}
    for i in range(len(s)-1):
        counts[s[i:i+2]]=counts.get(s[i:i+2],0)+1
    # build adjacency with remaining counts
    from collections import defaultdict
    adj=defaultdict(dict)
    for k,v in counts.items():
        adj[k[0]][k[1]]=v
    # find start: a node with outdeg=indeg+1 (start), else any
    outd={a:sum(d.values()) for a,d in adj.items()}
    ind=defaultdict(int)
    for a,d in adj.items():
        for b,c in d.items(): ind[b]+=c
    start=None
    for a in outd:
        if outd[a]-ind[a]==1: start=a
    if start is None: start=s[0]
    # Hierholzer to get Eulerian path (random)
    stack=[start]; path=[]
    adj2={a:dict(d) for a,d in adj.items()}
    while stack:
        v=stack[-1]
        outs=[b for b,c in adj2.get(v,{}).items() if c>0]
        if outs:
            b=random.choice(outs); adj2[v][b]-=1; stack.append(b)
        else:
            path.append(stack.pop())
    path=path[::-1]
    return ''.join(path)

obs=allorf(seq)
print('observed ORFs >=300nt:', sorted(obs, reverse=True))
longest_obs=max(obs)

big=[]; longs=[]
for t in range(60):
    s=dinuc_shuffle(seq)
    lo=allorf(s)
    big.append(sum(1 for x in lo if x>=800))
    longs.append(max(lo) if lo else 0)
print('dinuc-shuffle: mean #ORFs>=800nt', statistics.mean(big), 'max', max(big))
print('dinuc-shuffle longest ORF: mean',round(statistics.mean(longs)), 'max', max(longs))
"}
